/* 일반 본문 문장처럼 보이지만 클릭 가능한 서스펜스 메시지 스타일 (밑줄 표시) */
.story-content .suspense-msg {
    font-family: inherit;
    font-size: 1rem;
    font-weight: normal;
    color: var(--office-text);
    text-align: left;
    margin: 0;
    max-width: none;
    letter-spacing: -0.01em;
    text-shadow: none;
    animation: none;
    text-decoration: underline;
    cursor: pointer;
}

@keyframes suspensePulse {

    0%,
    100% {
        opacity: 0.6;
        text-shadow: 0 0 6px rgba(255, 107, 107, 0.3);
        transform: scale(0.99);
    }

    50% {
        opacity: 1;
        text-shadow: 0 0 15px rgba(255, 107, 107, 0.9);
        transform: scale(1.01);
    }
}

/* --- ending-details 아코디언 인터랙션 최적화 --- */
