    background: transparent;
    padding: 0;
}

.story-content details.ending-details summary {
    list-style: none;
    outline: none;
    cursor: pointer;
    background: transparent;
    border: none;
    padding: 0;
    display: block;
    margin: 1em 0;
}

.story-content details.ending-details summary::-webkit-details-marker {
    display: none;
}

.story-content details.ending-details summary::marker {
    display: none;
}

